import * as React from "react"

function ColorChangingButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="color-changing-button"
      className={className}
      {...props}
    >
      <button id="change-button" className="bg-red-500 text-white px-4 py-2 rounded-lg">
          Change Color!
      </button>


    </div>
  )
}

export { ColorChangingButton }
